func expandFirestoreFieldTtlConfig(v interface{}, d tpgresource.TerraformResourceData, config *transport_tpg.Config) (interface{}, error) {
	if v == nil {
		return nil, nil
	}
	l := v.([]interface{})
	if len(l) == 0 {
		return nil, nil
	}
	// A set (but possibly) empty value.
	transformed := make(map[string]interface{})
	if l[0] != nil {
		original := l[0].(map[string]interface{})
		originalValue := original["expiration_offset"]
		if val := reflect.ValueOf(originalValue); val.IsValid() && !tpgresource.IsEmptyValue(val) {
			transformed["expiration_offset"] = originalValue
		}
	}
	return transformed, nil
}
